require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();$rows=$p->query("SELECT o.*,c.name customer FROM orders o LEFT JOIN customers c ON c.id=o.customer_id WHERE o.art_status<>'Não se aplica' AND o.status<>'Cancelado' ORDER BY o.delivery_date")->fetchAll();page_head('Aprovação de arte');?>
<div class="card"><div class="table"><table><tr><th>Pedido</th><th>Cliente</th><th>Entrega</th><th>Arte</th><th>Etapa</th><th></th></tr><?php foreach($rows as $o):?><tr><td><?=e($o['number'])?></td><td><?=e($o['customer'])?></td><td><?=e($o['delivery_date'])?></td><td><span class="badge <?=badge_class($o['art_status'])?>"><?=e($o['art_status'])?></span></td><td><?=e($o['production_stage'])?></td><td><a class="btn" href="order.php?id=<?=$o['id']?>">Gerenciar</a></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>